import { parentPort } from "node:worker_threads";

/** Syntax is generated by the request walker; only bounded string slices need escaping. */
export type JsonPacketPart = string | { text: string };

parentPort?.on("message", (message: { action: "ping" } | { parts: JsonPacketPart[] }) => {
	if ("action" in message) {
		parentPort?.postMessage({ ready: true });
		return;
	}
	try {
		parentPort?.postMessage({
			text: message.parts
				.map((part) => (typeof part === "string" ? part : JSON.stringify(part.text).slice(1, -1)))
				.join(""),
		});
	} catch {
		parentPort?.postMessage({ error: "Request JSON escaping failed" });
	}
});
